function renderAll(){ensureGroupUi();ensurePasswordForm();ensureSystemSettingsForm();ensureMultiProviderForms();renderProviderOptions(selectedProviderName);installMultiProviderHandlers();renderMonitor();renderNotify();renderEvents();renderUpdate();fill('notifyForm',state.settings||{});fill('systemSettingsForm',{site_title:'服务器自动监控',site_description:'EdgeOne Pages 按探测间隔执行 HTTP(S) + API 检测；连续失败 3 次后确认异常并执行重启。',timezone:'Asia/Shanghai',data_retention_days:30,reboot_limit_window:'hour',default_daily_reboot_limit:3,suspect_threshold:3,recover_success_threshold:1,admin_overview_range:'24h',admin_monitor_range:'24h',...(state.settings||{})});fill('passwordForm',{});syncProviderPreset($('setupForm'),false);syncNotifyFields($('setupForm'));syncNotifyFields($('notifyForm'))}
async function loadOverview(){state=await api('/api/admin/overview');renderAll();if((state.settings||{}).setup_completed==='1')showApp();else if(token)showWizard(2);else showLogin();return state}
async function enter(){await loadOverview();localStorage.setItem('zjmf_admin_token',token);toast('已登录，控制台可操作','ok')}
