async function restartTutorial(){if(!confirm('确定要重走初始教程吗？现有监控项、服务商、通知、日志和设置会被清空，但管理密码保留。'))return;await task('重走初始教程',async()=>{const x=await api('/api/admin/setup/reset',{method:'POST'});show(x);clearSetupDraft();localStorage.removeItem('zjmf_admin_token');token='';location.reload();return x}).catch(()=>{})}
function openServer(s={}){if(!(state.providers||[]).length){toast('请先在设置中添加魔方财务 IDC','bad');tab('settings');return}ensureMultiProviderForms();renderProviderOptions(selectedProviderName);renderServerGroupOptions(s.group_id||'');const provider=String(s.provider||'').trim()||defaultProviderName();const remoteId=s.remote_id||String(s.id||'').split('::').pop();fill('serverForm',{provider,daily_reboot_limit:Number(state.settings.default_daily_reboot_limit||3),enabled:true,check_method:'http_then_api',http_method:'GET',http_expected_status:'200-399',tcp_port:443,recovery_action:'reboot',group_id:'',sort_order:0,...s,id:s.id||'',remote_id:remoteId,provider,check_interval:state.settings.check_interval||300,api_timeout_ms:Number(state.settings.api_timeout||60)*1000});$('serverProviderSelect').value=provider;autoFillHttpUrl($('serverForm'));syncProbeFields($('serverForm'));const label=(state.providers||[]).find(item=>item.name===provider)?.display_name||provider;$('serverIdHint').textContent=remoteId?label+' · 产品 ID #'+remoteId:'';$('editModal').classList.remove('hidden')}
function closeServer(){$('editModal').classList.add('hidden')}function openNotify(){fill('notifyForm',{webhook_name:'pushplus',webhook_type:'pushplus',webhook_url:'https://www.pushplus.plus/send',webhook_timeout:10000,webhook_headers:'{\\n  "Content-Type": "application/json"\\n}',webhook_template:'{{message}}',notify_token:'',notify_target:'',notify_secret:'',notify_failure_silence:false,...state.settings});syncNotifyFields($('notifyForm'));$('notifyModal').classList.remove('hidden')}function closeNotify(){$('notifyModal').classList.add('hidden')}
