async function submitSetup(e){e.preventDefault();autoAddCurrentSelection();const b=formData($('setupForm'));const providers=[...new Map(setupImports.map((item)=>[item.provider.name,item.provider])).values()];const servers=setupImports.map((item)=>({...item.server,check_method:b.check_method||item.server.check_method||'service_then_power',http_method:b.http_method||item.server.http_method||'GET',http_expected_status:b.http_expected_status||item.server.http_expected_status||'200-399',daily_reboot_limit:Number(b.daily_reboot_limit||item.server.daily_reboot_limit||3),probe_timeout_ms:Number(b.api_timeout_ms||item.server.probe_timeout_ms||60000)}));const payload={providers,servers,settings:{check_interval:Number(b.check_interval||300),api_timeout_ms:Number(b.api_timeout_ms||60000),default_daily_reboot_limit:Number(b.daily_reboot_limit||3),reboot_limit_window:b.reboot_limit_window||'hour'},notification:{enabled:b.notify_enabled==='on',type:b.webhook_type||'pushplus',webhook_url:b.webhook_url||'',pushplus_token:b.pushplus_token||'',notify_token:b.notify_token||b.pushplus_token||'',notify_target:b.notify_target||'',notify_secret:b.notify_secret||'',notify_failure_silence:b.notify_failure_silence==='on'}};const x=await api('/api/admin/setup',{method:'POST',body:JSON.stringify(payload)});show(x);clearSetupDraft();await loadOverview();return x}
