function installMultiProviderHandlers(){const providerForm=$('providerForm'),serverForm=$('serverForm');if(providerForm){providerForm.onsubmit=e=>{e.preventDefault();task('保存 IDC',async()=>{const payload=providerPayload(e.target);if(!payload.api_password)delete payload.api_password;selectedProviderName=payload.name;const x=await api('/api/admin/providers',{method:'POST',body:JSON.stringify(payload)});show(x);await loadOverview();return x}).catch(()=>{})};const select=$('providerSelect');if(select)select.onchange=()=>select.value?loadProviderForm(select.value):newProviderForm('custom');const newButton=$('newProviderBtn');if(newButton)newButton.onclick=()=>newProviderForm('custom');const testButton=$('testProviderBtn');if(testButton)testButton.onclick=()=>task('测试 IDC 连接',testProviderConnection).catch(()=>{});const type=providerForm.querySelector('[name="provider_type"]');if(type)type.onchange=()=>syncProviderPreset(providerForm,true)}if(serverForm)serverForm.onsubmit=e=>{e.preventDefault();task('保存服务器',async()=>{const b=formData(e.target);if(!b.provider)throw new Error('请选择所属 IDC');if(!b.remote_id)throw new Error('请填写魔方财务产品 ID');const settings={check_interval:Number(b.check_interval||300),api_timeout:Math.max(1,Math.ceil(Number(b.api_timeout_ms||60000)/1000))};delete b.check_interval;delete b.api_timeout_ms;if(!b.id)delete b.id;b.name=b.name||'服务器 #'+b.remote_id;b.enabled=b.enabled==='true';if(b.daily_reboot_limit!==undefined)b.daily_reboot_limit=Number(b.daily_reboot_limit||3);b.tcp_port=Number(b.tcp_port||0);b.probe_timeout_ms=Number(b.probe_timeout_ms||settings.api_timeout*1000);const x=await api('/api/admin/servers',{method:'POST',body:JSON.stringify(b)});await api('/api/admin/settings',{method:'POST',body:JSON.stringify(settings)});closeServer();await loadOverview();return x}).catch(()=>{})}}
